// Question editing extension: keep the original multidimensional-table implementation.
function qfocusRange(source, field) {
  const offset = source.match(/^---\r?\n[\s\S]*?\r?\n---(?:\r?\n|$)/)?.[0].length || 0;
  const body = source.slice(offset);
  const heading = /^##[ \t]+题目[ \t]*\r?$/m.exec(body);
  const separator = /^\?[ \t]*\r?$/m.exec(body);
  const origin = /^##[ \t]+来源[ \t]*\r?$/m.exec(body);
  if (!heading || !separator || separator.index <= heading.index) throw Error('未识别题目和 ? 分隔符，请用原 Markdown 编辑。');
  const afterLine = position => { const newline = source.indexOf('\n', position); return newline < 0 ? source.length : newline + 1; };
  const start = field === '题面' ? afterLine(offset + heading.index) : afterLine(offset + separator.index);
  const end = field === '题面' ? offset + separator.index : origin ? offset + origin.index : source.length;
  if(end < start) throw Error('题目分区顺序异常。');
  return { start, end, text: source.slice(start, end) };
}
function qfocusMerge(latest, field, original, draft) {
  const range = qfocusRange(latest, field);
  if(range.text !== original) throw Error('同一分区已发生修改，未覆盖原文。');
  return latest.slice(0, range.start) + draft + latest.slice(range.end);
}
